bounded_host_request.command:
set -eu
root="$(git rev-parse --show-toplevel)"
test "$(realpath "$root")" = /home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot || exit 70
c="$(docker ps --filter label=com.docker.compose.service=gaybbs --format '{{.ID}}')"
test "$(printf '%s\n' "$c" | sed '/^$/d' | wc -l)" -eq 1 || exit 71
expected="$(docker image inspect --format '{{.Id}}' gace-tgtumbler-gaybbs:shared-0145893)"
actual="$(docker inspect --format '{{.Image}}' "$c")"
test "$actual" = "$expected" || exit 72
docker logs "$c" 2>&1 | grep -q 'GAYBBS_BOT_READY' || exit 73
docker exec "$c" node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module -e '
import {readFileSync} from "node:fs";
const token=readFileSync("/run/secrets/bot_token","utf8").trim();
for(const scope of [{type:"default"},{type:"all_private_chats"}]){
 const q=new URLSearchParams({scope:JSON.stringify(scope)});
 const r=await fetch("https://api.telegram.org/bot"+token+"/getMyCommands?"+q);
 const j=await r.json();
 if(!r.ok||!j.ok||!Array.isArray(j.result))process.exit(74);
 if(j.result.length!==0)process.exit(75);
}
console.log("DM_COMMAND_MENU_EMPTY");
' || exit 76
systemctl --user is-active --quiet gace-userbot-verify.service || exit 77
echo GAYBBS_LIVE_IMAGE_AND_COMMAND_SUPPRESSION_PASS
